-- Prepares a Chinook 1.4.5 database (https://github.com/lerocha/chinook-database, MIT) on PostgreSQL for the
-- EclipseLink MCP samples. Run it as a superuser after the upstream Chinook_PostgreSql.sql, connected to the
-- chinook database (setup-postgresql.sh does both). chinook-mcp-h2.sql makes the same changes on H2.
--
-- Upstream Chinook has no optimistic lock versions and no generated keys, so it can only be read safely. The
-- changes below are what a DBA would make to let agents write it:
--   * a VERSION column (starting at 1) on each table whose rows agents may change; every writer increments it
--   * playlist_track.added_at, so adding a track to a playlist records when
--   * database-generated keys on each table agents add rows to, starting after the shipped data
--   * two accounts: mcp_reader (read only) and mcp_store (only the changes the music-store sample makes)

-- Optimistic lock versions
ALTER TABLE artist   ADD COLUMN version INT DEFAULT 1 NOT NULL;
ALTER TABLE album    ADD COLUMN version INT DEFAULT 1 NOT NULL;
ALTER TABLE track    ADD COLUMN version INT DEFAULT 1 NOT NULL;
ALTER TABLE customer ADD COLUMN version INT DEFAULT 1 NOT NULL;
ALTER TABLE playlist ADD COLUMN version INT DEFAULT 1 NOT NULL;

-- When a track was put on a playlist (NULL for the shipped data)
ALTER TABLE playlist_track ADD COLUMN added_at TIMESTAMP;

-- Generated keys, after the highest key in the 1.4.5 data
ALTER TABLE artist       ALTER COLUMN artist_id       ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 276);
ALTER TABLE album        ALTER COLUMN album_id        ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 348);
ALTER TABLE track        ALTER COLUMN track_id        ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 3504);
ALTER TABLE customer     ALTER COLUMN customer_id     ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 60);
ALTER TABLE invoice      ALTER COLUMN invoice_id      ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 413);
ALTER TABLE invoice_line ALTER COLUMN invoice_line_id ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 2241);
ALTER TABLE playlist     ALTER COLUMN playlist_id     ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 19);

-- Accounts, recreated each run (the upstream script drops and recreates the database first). The passwords are the sample's; use your own for anything but a local try-out.
DROP ROLE IF EXISTS mcp_reader;
CREATE ROLE mcp_reader LOGIN PASSWORD 'reader';
GRANT CONNECT ON DATABASE chinook TO mcp_reader;
GRANT USAGE ON SCHEMA public TO mcp_reader;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO mcp_reader;

DROP ROLE IF EXISTS mcp_store;
CREATE ROLE mcp_store LOGIN PASSWORD 'store';
GRANT CONNECT ON DATABASE chinook TO mcp_store;
GRANT USAGE ON SCHEMA public TO mcp_store;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO mcp_store;
GRANT INSERT ON artist, album, track, customer, invoice, invoice_line, playlist, playlist_track TO mcp_store;
GRANT UPDATE ON artist, album, track, customer, playlist TO mcp_store;
GRANT DELETE ON playlist, playlist_track TO mcp_store;
-- EclipseLink reads a generated key back with lastval(), which needs the identity's sequence
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO mcp_store;
